void usbhs_pkt_push ( struct usbhs_pipe * pipe , struct usbhs_pkt * pkt , void * done ( struct usbhs_priv * priv , struct usbhs_pkt * pkt ) , void * buf , int len , int zero , int sequence ) { struct usbhs_priv * priv = usbhs_pipe_to_priv ( pipe ) ; struct device * dev = usbhs_priv_to_dev ( priv ) ; unsigned long flags ; if ( ! done ) { dev_err ( dev , "no done function\n" ) ; return ; } usbhs_lock ( priv , flags ) ; if ( ! pipe -> handler ) { dev_err ( dev , "no handler function\n" ) ; pipe -> handler = & usbhsf_null_handler ; } list_move_tail ( & pkt -> node , & pipe -> list ) ; pkt -> buf = buf ; pkt -> handler = pipe -> handler ; pkt -> length = len ; pkt -> zero = zero ; pkt -> actual = 0 ; pkt -> done = done ; pkt -> sequence = sequence ; usbhs_unlock ( priv , flags ) ; } 